<script setup lang="tsx">
import type { WatchStopHandle } from "vue";
import { computed, onBeforeUnmount, onMounted, ref, watch } from "vue";
import { useRoute, useRouter } from "vue-router";
import { useCurrentInstance } from "@/util";
import { GetCommonErrorCode, ShowErrorTips } from "@/util/tips";
import { GetCollectionList, ParseCollection } from "@/apis/collection.ts";
import { Collection, CollectionEditRequest, CollectionView } from "@/types/collection.ts";
import { handleGotoUsername } from "@/util/router.ts";
import { useBreakpoint } from "@/composables/useBreakpoint";

const route = useRoute();
const router = useRouter();
const { globalProperties } = useCurrentInstance();
const { isMobile } = useBreakpoint();

let viewActive = false;
let watchHandle: WatchStopHandle | null = null;
const confirmLoading = ref(false);

const listColumns = ref([
  {
    title: "ID",
    colKey: "id",
    cell: (_: any, data: any) => {
      return (
        <t-button variant="text" onClick={() => handleGotoCollection(data.row.id)}>
          {data.row.id}
        </t-button>
      );
    },
  },
  {
    title: "标题",
    colKey: "title",
    cell: (_: any, data: any) => {
      return (
        <t-button variant="text" onClick={() => handleGotoCollection(data.row.id)}>
          {data.row.title}
        </t-button>
      );
    },
  },
  {
    title: "负责人",
    colKey: "inserterNickname",
    cell: (_: any, data: any) => {
      return (
        <t-button variant="text" onClick={() => handleGotoUsername(router, data.row.inserterUsername)}>
          {data.row.inserterNickname}
        </t-button>
      );
    },
  },
  {
    title: "开始时间",
    colKey: "startTime",
  },
  {
    title: "结束时间",
    colKey: "endTime",
  },
]);

const dataLoading = ref(false);

let currentPage = 1;
let currentPageSize = 50;

const pagination = ref({
  current: currentPage,
  pageSize: currentPageSize,
  defaultCurrent: currentPage,
  defaultPageSize: currentPageSize,
  total: 0,
  pageSizeOptions: [50, 100],
});

const collectionViews = ref<CollectionView[]>();

const visibleColumns = computed(() => {
  if (isMobile.value) {
    return listColumns.value.filter(
      (col) => col.colKey !== "startTime" && col.colKey !== "endTime"
    );
  }
  return listColumns.value;
});

const collectionSearchForm = ref({
  title: "",
  username: "",
});

const collectionCreateForm = ref<CollectionEditRequest>({
  title: "",
  description: "",
  open_time: [],
});

const handleGotoCollection = (id: string) => {
  if (!id) {
    return;
  }
  router.push({ path: "/collection/" + id });
};

const handleSearchCollection = async () => {
  await router.push({
    query: {
      ...route.query,
      title: collectionSearchForm.value.title,
      username: collectionSearchForm.value.username,
      page: 1,
      page_size: pagination.value.defaultPageSize,
    },
  });
};

// 重置筛选条件
const handleResetSearch = async () => {
  collectionSearchForm.value.title = "";
  collectionSearchForm.value.username = "";
  await router.push({
    query: {
      ...route.query,
      title: "",
      username: "",
      page: 1,
      page_size: pagination.value.defaultPageSize,
    },
  });
};

// 移动端筛选 Drawer 显隐状态
const showFilterDrawer = ref(false);

// 当前已激活的筛选条件数量，用于「筛选」按钮徽标提示
const activeFilterCount = computed(() => {
  let count = 0;
  if (collectionSearchForm.value.title) count++;
  if (collectionSearchForm.value.username) count++;
  return count;
});

// 移动端 Drawer 中的搜索：复用桌面端逻辑，搜索后关闭抽屉
const handleDrawerSearch = async () => {
  await handleSearchCollection();
  showFilterDrawer.value = false;
};

// 移动端 Drawer 中的重置：复用桌面端逻辑
const handleDrawerReset = async () => {
  await handleResetSearch();
};

const fetchData = async (paginationInfo: { current: number; pageSize: number }, needLoading: boolean) => {
  if (needLoading) {
    dataLoading.value = true;
  }
  try {
    const { current, pageSize } = paginationInfo;
    const res = await GetCollectionList(current, pageSize);
    collectionViews.value = [];
    if (res.code === 0) {
      const responseList = res.data.list as Collection[];
      for (let i = 0; i < responseList.length; i++) {
        const item = responseList[i];
        const result = ParseCollection(item);
        collectionViews.value?.push(result);
      }
      pagination.value = { ...pagination.value, total: res.data.total_count };
    } else {
      if (needLoading) {
        ShowErrorTips(globalProperties, res.code);
      }
    }
  } catch (err) {
    console.error(err);
    if (needLoading) {
      ShowErrorTips(globalProperties, GetCommonErrorCode());
    }
  } finally {
    if (needLoading) {
      dataLoading.value = false;
    }
  }
};

const onPageChange = async (pageInfo: { current: number; pageSize: number }) => {
  // 更新 URL 查询参数
  await router.push({
    query: { ...route.query, page: pageInfo.current, page_size: pageInfo.pageSize },
  });
};

const handleCreateCollection = async () => {
  await router.push({ name: "collection-create" });
};

const handleConfirmCreate = async () => {
  confirmLoading.value = true;

  console.log("collectionCreateForm", collectionCreateForm.value);
};

// 初始化分页信息
onMounted(async () => {
  viewActive = true;

  watchHandle = watch(
    () => route.query,
    (newQuery) => {
      collectionSearchForm.value.title = (newQuery.title as string) || "";
      collectionSearchForm.value.username = (newQuery.username as string) || "";
      const queryPage = parseInt(newQuery.page as string) || pagination.value.defaultCurrent;
      const queryPageSize = parseInt(newQuery.page_size as string) || pagination.value.defaultPageSize;
      currentPage = queryPage;
      currentPageSize = queryPageSize;
      pagination.value = { ...pagination.value, current: currentPage, pageSize: currentPageSize };
      fetchData({ current: currentPage, pageSize: currentPageSize }, true);
    },
    { immediate: true }
  );
});

onBeforeUnmount(() => {
  viewActive = false;

  if (watchHandle) {
    watchHandle();
  }
});
</script>

<template>
  <!-- 移动端布局：顶部操作栏 + 列表 + 右侧筛选 Drawer -->
  <div v-if="isMobile" class="collection-list-mobile">
    <div class="mobile-toolbar">
      <t-button
        theme="default"
        variant="outline"
        class="mobile-toolbar-btn"
        @click="showFilterDrawer = true"
      >
        <template #icon>
          <t-icon name="filter" />
        </template>
        筛选
        <t-badge
          v-if="activeFilterCount > 0"
          :count="activeFilterCount"
          shape="round"
          color="var(--td-brand-color)"
          :offset="[6, -6]"
        />
      </t-button>
      <t-button theme="primary" class="mobile-toolbar-btn" @click="handleCreateCollection">
        <template #icon>
          <t-icon name="add" />
        </template>
        创建
      </t-button>
    </div>

    <t-card class="mobile-list-card">
      <div style="overflow-x: auto; width: 100%">
        <t-table
          :data="collectionViews"
          :columns="visibleColumns"
          row-key="id"
          vertical-align="top"
          :hover="true"
          :pagination="pagination"
          :loading="dataLoading"
          tableLayout="auto"
          @page-change="onPageChange"
          size="small"
        />
      </div>
    </t-card>

    <!-- 移动端筛选抽屉：复用桌面端筛选表单 -->
    <t-drawer
      v-model:visible="showFilterDrawer"
      header="筛选"
      placement="right"
      size="80%"
      :close-on-esc-keydown="true"
      :show-overlay="true"
    >
      <t-form :model="collectionSearchForm">
        <t-form-item label="标题">
          <t-input v-model="collectionSearchForm.title" placeholder="暂不支持模糊查询"></t-input>
        </t-form-item>
        <t-form-item label="负责人">
          <t-input v-model="collectionSearchForm.username" placeholder="仅支持输入完整用户名"></t-input>
        </t-form-item>
      </t-form>

      <template #footer>
        <t-space>
          <t-button theme="primary" @click="handleDrawerSearch">确定</t-button>
          <t-button theme="danger" variant="outline" @click="handleDrawerReset">重置</t-button>
        </t-space>
      </template>
    </t-drawer>
  </div>

  <!-- 桌面端布局：左右双栏，筛选在右侧 -->
  <t-row v-else>
    <t-col :span="9">
      <t-card style="margin: 10px">
        <div style="overflow-x: auto; width: 100%">
          <t-table
            :data="collectionViews"
            :columns="visibleColumns"
            row-key="id"
            vertical-align="top"
            :hover="true"
            :pagination="pagination"
            :loading="dataLoading"
            tableLayout="auto"
            @page-change="onPageChange"
            size="medium"
          />
        </div>
      </t-card>
    </t-col>
    <t-col :span="3">
      <div style="margin: 10px">
        <t-card class="sh-card">
          <t-form :model="collectionSearchForm">
            <t-form-item label="标题">
              <t-input v-model="collectionSearchForm.title" placeholder="暂不支持模糊查询"></t-input>
            </t-form-item>
            <t-form-item label="负责人">
              <t-input v-model="collectionSearchForm.username" placeholder="仅支持输入完整用户名"></t-input>
            </t-form-item>
            <t-form-item>
              <t-button theme="primary" @click="handleSearchCollection">提交</t-button>
            </t-form-item>
          </t-form>
        </t-card>
        <t-card class="sh-card">
          <t-space>
            <t-button @click="handleCreateCollection">创建</t-button>
          </t-space>
        </t-card>
      </div>
    </t-col>
  </t-row>
</template>

<style scoped>
.sh-card {
  margin: 10px;
}

/* 移动端列表页样式 */
.collection-list-mobile {
  padding: 10px;
}

.mobile-toolbar {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 10px;
}

/* 工具栏按钮平分剩余空间 */
.mobile-toolbar-btn {
  flex: 1;
}

.mobile-list-card {
  margin: 0;
}
</style>
